//! P2 eval parity gate, HCE side (docs/plans/PLAN_03_rust_port.md "Parity
//! verification"). Fixture is generated by `tools/js/eval_dump.mjs` from
//! the JS oracle (`frontend/shared/eval_core.js`), reusing the same
//! startpos + 20 seeded positions as tests/perft.rs. Regenerate with:
//!
//! ```sh
//! node tools/js/eval_dump.mjs > crates/shatrunz-core/tests/fixtures/eval_hce_fixture.json
//! ```

use serde::Deserialize;
use shatrunz_core::eval::hce::{evaluate_for_search, evaluate_position_white, Persona};
use shatrunz_core::game::Game;
use shatrunz_core::moves::{MoveTarget, Square};

#[derive(Debug, Deserialize)]
struct Fixture {
    positions: Vec<PositionCase>,
}

#[derive(Debug, Deserialize)]
struct PositionCase {
    #[allow(dead_code)]
    label: String,
    evals: Evals,
    #[serde(rename = "uciMoves", default)]
    uci_moves: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Evals {
    material: PersonaEval,
    positional: PersonaEval,
    aggressive: PersonaEval,
}

#[derive(Debug, Deserialize)]
struct PersonaEval {
    white: i32,
    #[serde(rename = "forSearch")]
    for_search: i32,
}

fn load_fixture() -> Fixture {
    let raw = include_str!("fixtures/eval_hce_fixture.json");
    serde_json::from_str(raw).expect("eval_hce_fixture.json must parse")
}

/// Minimal UCI move parser matching frontend/shared/uci.js's
/// `parseUCIMove`: file a-i, rank = 9-row. No promotion suffix appears in
/// these fixtures (auto-queen is inferred by `Game::execute_move` itself).
fn parse_uci(uci: &str) -> (Square, MoveTarget) {
    let bytes = uci.as_bytes();
    let from_file = (bytes[0] - b'a') as usize;
    let from_rank: usize = (bytes[1] - b'0') as usize;
    let to_file = (bytes[2] - b'a') as usize;
    let to_rank: usize = (bytes[3] - b'0') as usize;
    let from = Square { r: 9 - from_rank, c: from_file };
    let to = MoveTarget::plain(9 - to_rank, to_file);
    (from, to)
}

#[test]
fn hce_eval_matches_js_oracle() {
    let fixture = load_fixture();
    for case in &fixture.positions {
        let mut game = Game::new();
        for uci in &case.uci_moves {
            let (from, to) = parse_uci(uci);
            assert!(game.execute_move(from, to), "{}: replay move {uci} failed", case.label);
        }

        for (persona, expected) in [
            (Persona::Material, &case.evals.material),
            (Persona::Positional, &case.evals.positional),
            (Persona::Aggressive, &case.evals.aggressive),
        ] {
            let white = evaluate_position_white(&game.board, persona);
            assert_eq!(
                white, expected.white,
                "{}: evaluatePositionWhite({:?}) mismatch",
                case.label, persona
            );
            let for_search = evaluate_for_search(&game.board, game.turn, persona);
            assert_eq!(
                for_search, expected.for_search,
                "{}: evaluateForSearch({:?}) mismatch",
                case.label, persona
            );
        }
    }
}
